//! Windows: links the application icon into `bae.exe`, so Explorer, the taskbar and
//! Alt+Tab show it (and `shell` can load it with `Icon::from_resource`).
//!
//! `assets/icons/app/bae.res` is a compiled resource file generated by `cargo xtask icons`
//! (icon group 1). The MSVC linker accepts `.res` files as input, so no resource compiler
//! or build dependency is needed. `cargo xtask dist` checks that the packaged exe has it.

use std::env;
use std::path::PathBuf;

fn main() {
    let manifest = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("set by cargo"));
    let res = manifest.join("../../assets/icons/app/bae.res");
    println!("cargo:rerun-if-changed={}", res.display());
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os == "windows" && target_env == "msvc" {
        assert!(
            res.is_file(),
            "{} is missing; run `cargo xtask icons`",
            res.display()
        );
        println!("cargo:rustc-link-arg-bins={}", res.display());
    }
}
